function n(t,i={}){return Number.isFinite(t)?t.toLocaleString("en-US",i).replace(/,/g," "):"0"}function r(t){return n(t,{maximumFractionDigits:0})}function a(t){const i=Math.trunc(t*1e3)/1e3;return n(i,{minimumFractionDigits:3,maximumFractionDigits:3})}function m(t){const i=Math.trunc(t*100)/100;return n(i,{minimumFractionDigits:2,maximumFractionDigits:2})}function c(t){return Number.isFinite(t)?t.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2}):"0.00"}export{r as a,m as b,n as c,a as d,c as f};
